    accent: androidx.compose.ui.graphics.Color,
    modifier: Modifier = Modifier,
    glyphAlpha: (Int) -> Float = { 1f },
) {
    val paths = androidx.compose.runtime.remember {
        WORDMARK_GLYPHS.map { g ->
            androidx.compose.ui.graphics.vector.PathParser().parsePathString(g.pathData).toPath()
                .apply { fillType = androidx.compose.ui.graphics.PathFillType.EvenOdd }
        }
    }
    androidx.compose.foundation.Canvas(
        modifier.then(androidx.compose.ui.Modifier.size(height * (WORDMARK_W / WORDMARK_H), height))
            .androidx_semantics("openRS_")
    ) {
        val s = size.height / WORDMARK_H
        scale(s, s, pivot = androidx.compose.ui.geometry.Offset.Zero) {
            paths.forEachIndexed { i, p ->
                val a = glyphAlpha(i).coerceIn(0f, 1f)
                if (a > 0f) drawPath(p, (if (WORDMARK_GLYPHS[i].accent) accent else base).copy(alpha = a * (if (WORDMARK_GLYPHS[i].accent) accent.alpha else base.alpha)))
            }
        }
    }
}

private fun androidx.compose.ui.Modifier.androidx_semantics(label: String) =
    semantics { contentDescription = label }

// ── Telemetry / control icon family ─────────────────────────────────────────

/**
 * The sheet's symbol family. [whole] is the full glyph (one colour); [accentLayer] the sheet's blue
 * parts, drawn over it for the normal two-tone look (null = the symbol is all one colour in the sheet:
 * all-blue icons use the accent, the all-white gear uses the ink).
 */
enum class RsIcon(@androidx.annotation.DrawableRes val whole: Int, @androidx.annotation.DrawableRes val accentLayer: Int?, val allAccent: Boolean) {
    BOOST(com.openrs.dash.R.drawable.ic_tt_boost, com.openrs.dash.R.drawable.ic_tt_boost_accent, false),
    COOLANT(com.openrs.dash.R.drawable.ic_tt_coolant, com.openrs.dash.R.drawable.ic_tt_coolant_accent, false),
    OIL(com.openrs.dash.R.drawable.ic_tt_oil, com.openrs.dash.R.drawable.ic_tt_oil_accent, false),
    TYRE(com.openrs.dash.R.drawable.ic_tt_tyre, null, true),
    BATTERY(com.openrs.dash.R.drawable.ic_tt_battery, null, true),
    FUEL(com.openrs.dash.R.drawable.ic_tt_fuel, null, true),
    GEAR(com.openrs.dash.R.drawable.ic_tt_gear, null, false),
    TRIP(com.openrs.dash.R.drawable.ic_tt_trip, null, true),
    GARAGE(com.openrs.dash.R.drawable.ic_tt_garage, com.openrs.dash.R.drawable.ic_tt_garage_accent, false),
    SETTINGS(com.openrs.dash.R.drawable.ic_tt_settings, com.openrs.dash.R.drawable.ic_tt_settings_accent, false),
    TRACTION(com.openrs.dash.R.drawable.ic_tt_traction, null, true),
    CONNECTED(com.openrs.dash.R.drawable.ic_tt_connected, null, true),
}

/**
 * Icon treatments. NORMAL keeps the sheet's ink + blue; every other tone paints the whole glyph one
 * colour, so a warning / critical / unavailable state is never outweighed by the decorative blue.
 * MUTED is an inactive control (nav tab, idle button) — one quiet colour, like the old nav icons.
 */
enum class IconTone { NORMAL, MUTED, SELECTED, WARNING, CRITICAL, UNAVAILABLE }

@androidx.compose.runtime.Composable
fun TelemetryIcon(
    icon: RsIcon,
    tone: IconTone,
    size: androidx.compose.ui.unit.Dp,
    modifier: Modifier = Modifier,
    contentDescription: String? = null,
) {
    val accent = LocalThemeAccent.current
    val ink = Frost
    val whole = when (tone) {
        IconTone.NORMAL -> if (icon.allAccent) accent else ink
        IconTone.MUTED -> Dim
        IconTone.SELECTED -> actionInk(accent)   // DAY: the darker readable blue; NIGHT: the accent
        IconTone.WARNING -> Warn
        IconTone.CRITICAL -> Orange
        IconTone.UNAVAILABLE -> Dim.copy(alpha = 0.5f)
    }
    androidx.compose.foundation.layout.Box(modifier.size(size)) {
        androidx.compose.material3.Icon(androidx.compose.ui.res.painterResource(icon.whole), contentDescription,
            androidx.compose.ui.Modifier.matchParentSize(), tint = whole)
        if (tone == IconTone.NORMAL && icon.accentLayer != null)
            androidx.compose.material3.Icon(androidx.compose.ui.res.painterResource(icon.accentLayer), null,
                androidx.compose.ui.Modifier.matchParentSize(), tint = accent)
    }
}

/** Icon tone for a reading's [Level] (alerts take the whole glyph; stale / missing read unavailable). */
fun Level.iconTone(): IconTone = when (this) {
    Level.CRIT -> IconTone.CRITICAL
    Level.WARN -> IconTone.WARNING
    Level.STALE, Level.NONE -> IconTone.UNAVAILABLE
    else -> IconTone.NORMAL
}

// ── Opening presentation ────────────────────────────────────────────────────

/** Background of the system splash and the opening presentation (the sheet's phone screen, #030609). */
val SplashBg = androidx.compose.ui.graphics.Color(0xFF030609)

/**
 * The sheet's opening screen — wordmark, tagline and the front-view RS — drawn over the app on a cold
 * start. No timer: it stays only until the dashboard behind it has drawn its first frame, then fades
 * out (450 ms) to reveal it. Not shown again on rotation / recreation.
 */
@androidx.compose.runtime.Composable
fun OpeningPresentation(onFinished: () -> Unit) {
    val alpha = androidx.compose.runtime.remember { androidx.compose.animation.core.Animatable(1f) }
    androidx.compose.runtime.LaunchedEffect(Unit) {
        // Two frames: the first composes the dashboard underneath, the second has it drawn
        androidx.compose.runtime.withFrameNanos { }
        androidx.compose.runtime.withFrameNanos { }
        alpha.animateTo(0f, androidx.compose.animation.core.tween(450, easing = androidx.compose.animation.core.FastOutSlowInEasing))
        onFinished()
    }
    val a = alpha.value
    androidx.compose.foundation.layout.BoxWithConstraints(
        androidx.compose.ui.Modifier.fillMaxSize()
            .graphicsLayer { this.alpha = a }
            .background(SplashBg)
            // swallow touches while visible so a tap doesn't land on the dashboard mid-fade
            .pointerInput(Unit) { awaitPointerEventScope { while (true) awaitPointerEvent() } },
    ) {
        val w = maxWidth
        val h = maxHeight
        val wordH = (w * 0.74f) / (WORDMARK_W / WORDMARK_H)
        androidx.compose.foundation.layout.Column(
            androidx.compose.ui.Modifier.fillMaxSize().padding(top = h * 0.17f),
            horizontalAlignment = androidx.compose.ui.Alignment.CenterHorizontally,
        ) {
            Wordmark(wordH, base = androidx.compose.ui.graphics.Color(0xFFF2F4F7), accent = androidx.compose.ui.graphics.Color(0xFF0A8CFF))
            androidx.compose.foundation.layout.Spacer(androidx.compose.ui.Modifier.height(wordH * 0.42f))
            androidx.compose.material3.Text(
                "Built for the car Ford should\nhave given us an app for.",
                color = androidx.compose.ui.graphics.Color(0xFFE8ECF2),
                fontSize = (w.value * 0.042f).coerceIn(14f, 19f).sp,
                lineHeight = (w.value * 0.058f).coerceIn(19f, 26f).sp,
                fontFamily = androidx.compose.ui.text.font.FontFamily.SansSerif,
                textAlign = androidx.compose.ui.text.style.TextAlign.Center,
            )
            androidx.compose.foundation.layout.Spacer(androidx.compose.ui.Modifier.weight(1f))
            // Front-view car at its own proportions (300 × 360 px art), as wide as the sheet's composition
            androidx.compose.foundation.Image(
                androidx.compose.ui.graphics.ImageBitmap.imageResource(com.openrs.dash.R.drawable.rs_splash_car), contentDescription = null,
                modifier = androidx.compose.ui.Modifier.fillMaxWidth(0.92f).heightIn(max = h * 0.55f)
                    .aspectRatio(300f / 360f),
                contentScale = androidx.compose.ui.layout.ContentScale.Fit,
                filterQuality = androidx.compose.ui.graphics.FilterQuality.High,
            )
            androidx.compose.foundation.layout.Spacer(androidx.compose.ui.Modifier.height(h * 0.06f))
        }
    }
}
